SELECT Generale.Data, Generale.EsitoComm, Luogo.Descrizione, Tipologia.Descrizione, Genere.Descrizione, Sum(Generale.Qta) AS SommaDiQta, Sum(Generale.Resto) AS SommaDiResto, Sum(Generale.QtaS) AS SommaDiQtaS, Sum(Generale.RestoS) AS SommaDiRestoS, Generale.Rapporo, Sum([qtas]*160+[restos]) AS Tot, Sum(IIf([genere].[Descrizione]='Vino' Or [genere].[Descrizione]='Galline',[qta],[qta]*6+[resto])) AS Pesinali, [rapporo]/6*[pesinali] AS CostoRApporto, [EsitoComm] & ' ' & [Tipologia].[Descrizione] & '. ' & [Luogo].[Descrizione] AS Tipo, IIf([Data]="1414-1415",[Pesinali]/2,IIf([Data]="1412",[pesinali],[Pesinali]/10)) AS Norm, IIf([Data]="1412","1412",IIf([Data]="1414-1415","1414-1415","1416-1425")) AS Nuovo
FROM ((Generale LEFT JOIN Genere ON Generale.IdGenere = Genere.IdGenere) LEFT JOIN Luogo ON Generale.IdLuogo = Luogo.IdLuogo) LEFT JOIN Tipologia ON Generale.IdTipologia = Tipologia.IdTipologia
GROUP BY Generale.Data, Generale.EsitoComm, Luogo.Descrizione, Tipologia.Descrizione, Genere.Descrizione, Generale.Rapporo, IIf([Data]="1412","1412",IIf([Data]="1414-1415","1414-1415","1416-1425"))
HAVING (((Generale.EsitoComm)="rendita") AND (Not (Genere.Descrizione) Is Null And (Genere.Descrizione)<>"Galline" And (Genere.Descrizione)<>"Vino" And (Genere.Descrizione)<>"Spalle"));
